package com.chatq.keyboardtests;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
final class ReplyWorkspaceChecks {
 static int count;static void ok(boolean v,String why){if(!v)throw new AssertionError(why);count++;}
 static JSONObject sample()throws Exception{return new JSONObject().put("schema",1).put("mode","polish").put("reply","合成对方消息127").put("polish","合成我的草稿127").put("context","合成背景").put("goal","礼貌").put("style","friendly").put("hadScreenshot",true);}
 static int run(final Context actual)throws Exception{
  final String dbName="qa127_chatq-generations.db";actual.deleteDatabase(dbName);
  Context context=new ContextWrapper(actual){public java.io.File getDatabasePath(String name){return actual.getDatabasePath("qa127_"+name);}public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences("qa127_"+name,mode);}public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory,DatabaseErrorHandler handler){return actual.openOrCreateDatabase("qa127_"+name,mode,factory,handler);}public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory){return actual.openOrCreateDatabase("qa127_"+name,mode,factory);}};
  SharedPreferences prefs=context.getSharedPreferences("chatq_reply_drafts_v1",0);prefs.edit().clear().commit();ClassLoader loader=actual.getClassLoader();Class<?> type=loader.loadClass("expo.modules.chatqkeyboard.ReplyDraftStore");Object drafts=type.getConstructor(Context.class).newInstance(context);Method save=type.getMethod("save",String.class),load=type.getMethod("load"),clear=type.getMethod("clear"),enable=type.getMethod("setEnabled",boolean.class);Object records=null;
  try{
   JSONObject initial=new JSONObject((String)load.invoke(drafts));ok(initial.getBoolean("enabled")&&initial.isNull("value"),"fresh drafts empty and local-only");
   save.invoke(drafts,sample().toString());ok(!prefs.getAll().toString().contains("合成"),"draft text encrypted at rest");Object reopened=type.getConstructor(Context.class).newInstance(context);JSONObject value=new JSONObject((String)load.invoke(reopened)).getJSONObject("value");ok(value.getString("reply").equals("合成对方消息127")&&value.getString("polish").equals("合成我的草稿127"),"separate reply/polish text restored");ok(value.getBoolean("hadScreenshot")&&!value.has("attachments"),"only screenshot absence reminder is persisted");
   for(String extra:new String[]{"attachments","apiKey","unknown"}){try{save.invoke(drafts,sample().put(extra,"not-allowed").toString());throw new AssertionError("unknown persisted");}catch(InvocationTargetException e){ok(e.getCause() instanceof IllegalArgumentException,"private/unknown fields rejected");}}
   enable.invoke(drafts,false);save.invoke(drafts,sample().toString());ok(!prefs.contains("value")&&!new JSONObject((String)load.invoke(drafts)).getBoolean("enabled"),"disabled storage never saves");enable.invoke(drafts,true);save.invoke(drafts,sample().toString());prefs.edit().putLong("updatedAt",System.currentTimeMillis()-8L*24*60*60*1000).commit();JSONObject expired=new JSONObject((String)load.invoke(drafts));ok(expired.getBoolean("expired")&&expired.isNull("value")&&!prefs.contains("value"),"seven-day expiry deletes archive");
   save.invoke(drafts,sample().toString());prefs.edit().putString("value","damaged").commit();try{load.invoke(drafts);throw new AssertionError("corrupt draft accepted");}catch(InvocationTargetException e){ok(e.getCause() instanceof IllegalStateException&&prefs.getString("value","").equals("damaged"),"corrupt data reported without silent overwrite");}clear.invoke(drafts);ok(new JSONObject((String)load.invoke(drafts)).isNull("value"),"explicit clear repairs storage");
   Class<?> storeType=loader.loadClass("expo.modules.chatqkeyboard.GenerationStore");records=storeType.getConstructor(Context.class).newInstance(context);List<String> replies=new ArrayList<>();for(int i=0;i<10;i++)replies.add("合成候选"+i);storeType.getMethod("save",String.class,List.class,String.class,String.class).invoke(records,"合成十条消息",replies,"app","reply");JSONObject backup=(JSONObject)storeType.getMethod("export").invoke(records);ok(backup.getJSONArray("records").getJSONObject(0).getJSONArray("replies").length()==10,"all ten candidates survive shared history");storeType.getMethod("validateBackup",JSONObject.class).invoke(records,backup);ok(!backup.toString().contains("合成我的草稿127")&&!backup.toString().contains("hadScreenshot"),"draft archive is excluded from backup");storeType.getMethod("clear").invoke(records);int restored=((Number)storeType.getMethod("restore",JSONObject.class).invoke(records,backup)).intValue();ok(restored==1,"ten-candidate backup restores: "+restored);ok(((JSONObject)storeType.getMethod("export").invoke(records)).getJSONArray("records").getJSONObject(0).getJSONArray("replies").length()==10,"restore does not truncate candidates");
   return count;
  }finally{if(records!=null)records.getClass().getMethod("close").invoke(records);actual.deleteDatabase("qa127_chatq-generations.db");prefs.edit().clear().commit();context.getSharedPreferences("chatq_keyboard",0).edit().clear().commit();}
 }
}
